const pptxgen = require('pptxgenjs');
const fs = require('fs');

const pptx = new pptxgen();
pptx.layout = 'LAYOUT_16X9';
pptx.author = 'OpenAI';
pptx.company = 'OpenAI';
pptx.subject = "Ethereum post-merge supply dynamics";
pptx.title = "Ultra Sound Money: Ethereum's Post-Merge Supply Dynamics and Monetary Premium";
pptx.lang = 'en-US';
pptx.theme = {
  headFontFace: 'Aptos Display',
  bodyFontFace: 'Aptos',
  lang: 'en-US'
};
pptx.defineLayout({ name: 'LAYOUT_16X9_CUSTOM', width: 10, height: 5.625 });
pptx.layout = 'LAYOUT_16X9_CUSTOM';
pptx.margin = 0;
pptx.defineSlideMaster({
  title: 'MASTER',
  background: { color: '07111F' },
  objects: []
});
pptx.defineSlideMaster({
  title: 'MASTER_LIGHT',
  background: { color: 'F6F8FB' },
  objects: []
});

const C = {
  bg: '07111F',
  panel: '0E1B2D',
  panel2: '12243A',
  ink: 'F6FBFF',
  muted: 'A8B6C8',
  eth: '627EEA',
  burn: 'FF6B4A',
  mint: '00D395',
  yellow: 'F4C542',
  light: 'F6F8FB',
  darkText: '172033',
  greyText: '5B6678',
  grid: 'D8DEE8',
  white: 'FFFFFF',
  purple: '8F6DFF',
  red: 'F05365'
};
const W = 10, H = 5.625;

function title(slide, text, sub, light=false) {
  slide.addText(text, { x: 0.45, y: 0.28, w: 8.5, h: 0.52, margin: 0, fontFace: 'Aptos Display', fontSize: 20, bold: true, color: light ? C.darkText : C.ink, fit: 'shrink' });
  if (sub) slide.addText(sub, { x: 0.47, y: 0.82, w: 8.9, h: 0.28, margin: 0, fontSize: 7.8, color: light ? C.greyText : C.muted, charSpacing: 0.5, fit: 'shrink' });
  slide.addShape(pptx.ShapeType.line, { x: 0.45, y: 1.08, w: 9.1, h: 0, line: { color: light ? C.grid : '1B3352', width: 1 } });
}

function footer(slide, n, light=false) {
  slide.addText('ultrasound.money source brief', { x: 0.45, y: 5.25, w: 3.2, h: 0.16, margin: 0, fontSize: 6.5, color: light ? '7B8494' : '607086', charSpacing: 0.7 });
  slide.addText(String(n).padStart(2,'0'), { x: 9.2, y: 5.18, w: 0.36, h: 0.22, margin: 0, fontSize: 7.5, bold: true, color: light ? C.greyText : C.muted, align: 'right' });
}

function addStat(slide, x, y, w, h, value, label, opts={}) {
  const light = opts.light || false;
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.07, fill: { color: opts.fill || (light ? C.white : C.panel) }, line: { color: opts.line || (light ? 'E1E6EF' : '213B5D'), width: 1 }, shadow: opts.shadow === false ? undefined : { type: 'outer', color: '000000', opacity: light ? 0.10 : 0.20, blur: 1, angle: 45, offset: 1 } });
  slide.addText(value, { x: x+0.16, y: y+0.18, w: w-0.32, h: h*0.38, margin: 0, fontSize: opts.size || 22, bold: true, color: opts.color || (light ? C.darkText : C.ink), fit: 'shrink' });
  slide.addText(label, { x: x+0.16, y: y+h*0.58, w: w-0.32, h: h*0.24, margin: 0, fontSize: opts.labelSize || 7.5, color: opts.labelColor || (light ? C.greyText : C.muted), fit: 'shrink', breakLine: false });
}

function pill(slide, x, y, w, text, color=C.eth, bg='14253B') {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h: 0.24, rectRadius: 0.08, fill: { color: bg }, line: { color, width: 0.8 } });
  slide.addText(text, { x, y: y+0.055, w, h: 0.09, margin: 0, align: 'center', fontSize: 6.7, bold: true, color });
}

function wrapText(s, max=42) {
  const words = s.split(' '); let lines = [], line = '';
  for (const word of words) {
    if ((line + ' ' + word).trim().length > max) { lines.push(line); line = word; }
    else line = (line + ' ' + word).trim();
  }
  if (line) lines.push(line);
  return lines.join('\n');
}

function hbar(slide, items, x, y, w, rowH, maxVal, light=false, unit='') {
  items.forEach((d, i) => {
    const yy = y + i * rowH;
    slide.addText(d.name, { x, y: yy+0.03, w: 1.52, h: 0.16, margin: 0, fontSize: 7.2, color: light ? C.darkText : C.ink, bold: i < 2 });
    slide.addShape(pptx.ShapeType.rect, { x: x+1.65, y: yy+0.035, w: w-2.4, h: 0.16, fill: { color: light ? 'E7ECF4' : '1B2D47' }, line: { transparency: 100 } });
    const bw = (w-2.4) * (d.value / maxVal);
    slide.addShape(pptx.ShapeType.rect, { x: x+1.65, y: yy+0.035, w: Math.max(0.015, bw), h: 0.16, fill: { color: d.color || C.eth }, line: { transparency: 100 } });
    slide.addText(`${d.label || d.value}${unit}`, { x: x+w-0.66, y: yy+0.025, w: 0.65, h: 0.16, margin: 0, fontSize: 7, color: light ? C.greyText : C.muted, align: 'right' });
  });
}

function callout(slide, x, y, w, h, heading, body, light=false, accent=C.eth) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.06, fill: { color: light ? C.white : C.panel }, line: { color: light ? 'E1E6EF' : '223A5C', width: 1 } });
  slide.addShape(pptx.ShapeType.rect, { x, y, w: 0.055, h, fill: { color: accent }, line: { transparency: 100 } });
  slide.addText(heading, { x: x+0.18, y: y+0.14, w: w-0.32, h: 0.2, margin: 0, fontSize: 9.2, bold: true, color: light ? C.darkText : C.ink, fit: 'shrink' });
  slide.addText(body, { x: x+0.18, y: y+0.45, w: w-0.32, h: h-0.55, margin: 0, fontSize: 7.2, color: light ? C.greyText : C.muted, fit: 'shrink', breakLine: false });
}

function addDataSourceNote(slide, text, light=false) {
  slide.addText(text, { x: 0.45, y: 4.95, w: 8.9, h: 0.18, margin: 0, fontSize: 5.8, color: light ? '8992A1' : '708095', fit: 'shrink' });
}

// Slide 1
{
  const s = pptx.addSlide('MASTER');
  s.background = { color: C.bg };
  s.addShape(pptx.ShapeType.arc, { x: 6.6, y: -1.1, w: 4.2, h: 4.2, adjustPoint: 0.15, line: { color: C.eth, transparency: 12, width: 3 } });
  s.addShape(pptx.ShapeType.arc, { x: 7.2, y: 0.25, w: 3.2, h: 3.2, adjustPoint: 0.15, line: { color: C.mint, transparency: 20, width: 2 } });
