  s.addText("Ethereum's Supply Dynamics\n& Monetary Thesis", { x: 0.55, y: 1.05, w: 6.6, h: 1.22, margin: 0, fontFace: 'Aptos Display', fontSize: 34, bold: true, color: C.ink, breakLine: false, fit: 'shrink' });
  s.addText('Post-Merge ETH economics for crypto-native investors evaluating ETH as a monetary asset', { x: 0.58, y: 2.52, w: 5.8, h: 0.35, margin: 0, fontSize: 13.5, color: C.muted, fit: 'shrink' });
  addStat(s, 0.58, 3.35, 1.9, 0.92, '121.6M', 'current ETH supply', { color: C.ink });
  addStat(s, 2.72, 3.35, 1.55, 0.92, '0.1', 'avg base gas, Gwei', { color: C.yellow });
  addStat(s, 4.52, 3.35, 1.55, 0.92, '$2,243', 'ETH price', { color: C.mint });
  s.addShape(pptx.ShapeType.roundRect, { x: 6.92, y: 3.13, w: 2.42, h: 1.36, rectRadius: 0.08, fill: { color: '0A1626', transparency: 8 }, line: { color: '284B78', width: 1 } });
  s.addText('+0.83%/yr', { x: 7.12, y: 3.36, w: 2.02, h: 0.36, margin: 0, align: 'center', fontSize: 22, bold: true, color: C.red });
