  slide.addText(value, { x: x+0.16, y: y+0.18, w: w-0.32, h: h*0.38, margin: 0, fontSize: opts.size || 22, bold: true, color: opts.color || (light ? C.darkText : C.ink), fit: 'shrink' });
  slide.addText(label, { x: x+0.16, y: y+h*0.58, w: w-0.32, h: h*0.24, margin: 0, fontSize: opts.labelSize || 7.5, color: opts.labelColor || (light ? C.greyText : C.muted), fit: 'shrink', breakLine: false });
}

function pill(slide, x, y, w, text, color=C.eth, bg='14253B') {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h: 0.24, rectRadius: 0.08, fill: { color: bg }, line: { color, width: 0.8 } });
  slide.addText(text, { x, y: y+0.055, w, h: 0.09, margin: 0, align: 'center', fontSize: 6.7, bold: true, color });
}

function wrapText(s, max=42) {
  const words = s.split(' '); let lines = [], line = '';
  for (const word of words) {
    if ((line + ' ' + word).trim().length > max) { lines.push(line); line = word; }
    else line = (line + ' ' + word).trim();
  }
  if (line) lines.push(line);
  return lines.join('\n');
}

function hbar(slide, items, x, y, w, rowH, maxVal, light=false, unit='') {
  items.forEach((d, i) => {
    const yy = y + i * rowH;
    slide.addText(d.name, { x, y: yy+0.03, w: 1.52, h: 0.16, margin: 0, fontSize: 7.2, color: light ? C.darkText : C.ink, bold: i < 2 });
    slide.addShape(pptx.ShapeType.rect, { x: x+1.65, y: yy+0.035, w: w-2.4, h: 0.16, fill: { color: light ? 'E7ECF4' : '1B2D47' }, line: { transparency: 100 } });
    const bw = (w-2.4) * (d.value / maxVal);
    slide.addShape(pptx.ShapeType.rect, { x: x+1.65, y: yy+0.035, w: Math.max(0.015, bw), h: 0.16, fill: { color: d.color || C.eth }, line: { transparency: 100 } });
    slide.addText(`${d.label || d.value}${unit}`, { x: x+w-0.66, y: yy+0.025, w: 0.65, h: 0.16, margin: 0, fontSize: 7, color: light ? C.greyText : C.muted, align: 'right' });
  });
}

function callout(slide, x, y, w, h, heading, body, light=false, accent=C.eth) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.06, fill: { color: light ? C.white : C.panel }, line: { color: light ? 'E1E6EF' : '223A5C', width: 1 } });
  slide.addShape(pptx.ShapeType.rect, { x, y, w: 0.055, h, fill: { color: accent }, line: { transparency: 100 } });
  slide.addText(heading, { x: x+0.18, y: y+0.14, w: w-0.32, h: 0.2, margin: 0, fontSize: 9.2, bold: true, color: light ? C.darkText : C.ink, fit: 'shrink' });
  slide.addText(body, { x: x+0.18, y: y+0.45, w: w-0.32, h: h-0.55, margin: 0, fontSize: 7.2, color: light ? C.greyText : C.muted, fit: 'shrink', breakLine: false });
}

function addDataSourceNote(slide, text, light=false) {
  slide.addText(text, { x: 0.45, y: 4.95, w: 8.9, h: 0.18, margin: 0, fontSize: 5.8, color: light ? '8992A1' : '708095', fit: 'shrink' });
}

